-- ==========================================================================================
-- Memulihkan digit yang hilang: KTP, NPWP, rekening dan nomor batch
-- ==========================================================================================
-- Pemilik berkali-kali meminta agar tidak ada angka yang ditampilkan sebagai e+. Ternyata
-- masalahnya bukan di tampilan sama sekali. Angka itu sudah tersimpan rusak di dalam database:
--
--   rc_private.claim_sensitive : 1423 dari 1423 KTP terisi berbentuk 1.10304E+15
--                                266 NPWP dan 125 nomor rekening juga
--   public.claims              : 1703 batch upload, 1275 batch release,
--                                982 batch claim, 547 batch clearing
--
-- 1.10304E+15 hanya menyimpan enam angka berarti, sedangkan satu nomor KTP punya enam belas.
-- Sisanya tidak ada lagi di database, sehingga tidak ada perbaikan di sisi tampilan yang bisa
-- memunculkannya kembali. Nilai itu harus diambil ulang dari sumber.
--
-- Sumbernya masih utuh: data-rc/Compile.csv memuat 1424 KTP, 275 NPWP dan 391 nomor rekening,
-- dan TIDAK SATU PUN di antaranya berbentuk eksponen. Kerusakan terjadi pada langkah impor,
-- bukan pada data aslinya.
--
-- Berkas ini dihasilkan langsung dari Compile.csv, dengan No Document sebagai kunci - kunci itu
-- sudah diperiksa cocok dengan public.claims.no_doc.
--
-- YANG DISENTUH DAN YANG TIDAK
-- Satu nilai hanya ditimpa bila nilai yang sekarang kosong ATAU berbentuk eksponen, dan hanya
-- bila sumbernya memang berisi. Nilai yang sudah benar dibiarkan apa adanya, termasuk bila
-- seseorang sudah memperbaikinya lewat layar. Tidak ada baris yang ditambah maupun dihapus.
--
-- Aman dijalankan berulang: sesudah pertama kali tidak ada lagi nilai berbentuk eksponen yang
-- cocok dengan syaratnya.
-- ==========================================================================================

drop table if exists rc_sumber_digit;
create temporary table rc_sumber_digit(
  no_doc text primary key, ktp text, npwp text, no_rek text, nama_rek text,
  bank text, top_text text, b_upload text, b_release text, b_claim text, b_clearing text
) on commit drop;


-- Pola satu angka yang tertulis dalam notasi eksponen, misalnya 1.10304E+15.
create or replace temporary view rc_pola as select '^[0-9]+([.][0-9]+)?[Ee][+-]?[0-9]+$' as p;

update rc_private.claim_sensitive s
   set ktp            = case when nullif(x.ktp,'')      is not null
                              and (coalesce(s.ktp,'')='' or s.ktp ~ (select p from rc_pola))
                             then x.ktp else s.ktp end,
       npwp           = case when nullif(x.npwp,'')     is not null
                              and (coalesce(s.npwp,'')='' or s.npwp ~ (select p from rc_pola))
                             then x.npwp else s.npwp end,
       account_number = case when nullif(x.no_rek,'')   is not null
                              and (coalesce(s.account_number,'')='' or s.account_number ~ (select p from rc_pola))
                             then x.no_rek else s.account_number end,
       account_name   = case when nullif(x.nama_rek,'') is not null
                              and coalesce(s.account_name,'')=''
                             then x.nama_rek else s.account_name end,
       bank           = case when nullif(x.bank,'')     is not null
                              and coalesce(s.bank,'')=''
                             then x.bank else s.bank end,
       top_text       = case when nullif(x.top_text,'') is not null
                              and (coalesce(s.top_text,'')='' or s.top_text ~ (select p from rc_pola))
                             then x.top_text else s.top_text end
  from rc_sumber_digit x, public.claims c
 where c.no_doc = x.no_doc and s.claim_id = c.id;

update public.claims c
   set batch_upload   = case when nullif(x.b_upload,'')   is not null
                              and (coalesce(c.batch_upload,'')='' or c.batch_upload ~ (select p from rc_pola))
                             then x.b_upload else c.batch_upload end,
       batch_release  = case when nullif(x.b_release,'')  is not null
                              and (coalesce(c.batch_release,'')='' or c.batch_release ~ (select p from rc_pola))
                             then x.b_release else c.batch_release end,
       batch_claim    = case when nullif(x.b_claim,'')    is not null
                              and (coalesce(c.batch_claim,'')='' or c.batch_claim ~ (select p from rc_pola))
                             then x.b_claim else c.batch_claim end,
       batch_clearing = case when nullif(x.b_clearing,'') is not null
                              and (coalesce(c.batch_clearing,'')='' or c.batch_clearing ~ (select p from rc_pola))
                             then x.b_clearing else c.batch_clearing end
  from rc_sumber_digit x
 where c.no_doc = x.no_doc;

create or replace function rc_private.marker_20260928() returns boolean
language sql immutable set search_path='' as $$select true$$;
revoke all on function rc_private.marker_20260928() from public,anon;
grant execute on function rc_private.marker_20260928() to authenticated;

-- Ringkasan. Seluruh angka di bawah ini harus nol sesudah Run.
select 'Digit dipulihkan dari Compile.csv' as hasil,
 (select count(*) from rc_private.claim_sensitive where ktp ~ (select p from rc_pola)) as ktp_masih_eksponen,
 (select count(*) from rc_private.claim_sensitive where npwp ~ (select p from rc_pola)) as npwp_masih_eksponen,
 (select count(*) from rc_private.claim_sensitive where account_number ~ (select p from rc_pola)) as rekening_masih_eksponen,
 (select count(*) from public.claims where batch_upload ~ (select p from rc_pola)) as batch_upload_masih_eksponen,
 (select count(*) from public.claims where batch_release ~ (select p from rc_pola)) as batch_release_masih_eksponen,
 (select count(*) from public.claims where batch_claim ~ (select p from rc_pola)) as batch_claim_masih_eksponen,
 (select count(*) from public.claims where batch_clearing ~ (select p from rc_pola)) as batch_clearing_masih_eksponen,
 (select count(*) from rc_private.claim_sensitive where length(btrim(ktp))=16) as ktp_16_digit;
